@js:
if(/_\d\.html/.test(baseUrl)){
//第二页利用javascript解密
try{java.base64Decode(src.match(/var mytxt.*?['"](.*?)['"];/)[1])}
catch(e){
java.log(e);
java.log(baseUrl);
"第二页解密失败！链接\n"+baseUrl
}
}
//第一页常规方式获取
else java.getString("id.nr1@textNodes",false)

#htmlContent@html##<p id="contentTip"[\s\S]+##❎
<js>
list = java.getElement("@@id.subFrom@input").toArray()
if(list.length){
body="";
for(i=0;i<list.length;i++){
	body += list[i].attr("name")+"="+java.encodeURI(list[i].attr("value"))+"&"
	}
url = "https://www.damixs.co/get-page-data?"+Math.random();
option = {
	"method":"POST",
	"body":String(body).replace(/&$/,'')
	}
url = url+","+JSON.stringify(option)
j = java.ajax(url);
result = result + JSON.parse(j).data+"❎"
}else{
	result = result
	}
</js>

